  "sprint": {
    "days": 5,
    "max_crew": 3,
    "swarm_overhead": 0.15,
    "rollover_rates": {
      "once": 0.2,
      "twice": 0.05
    },
    "runs": 300,
    "decision_days": 1,
    "why": "One-week sprints of 5 working days (Nikhil, 26 Nov 2026).",
    "swarm_why": "A story longer than a sprint gets several engineers so it fits one (up to the 3 on the team); working on one story together costs 15% more time for hand-offs and reviews (Nikhil, 26 Nov 2026).",
    "rollover_why": "20% of stories roll over once and 5% twice (assumptions accepted by Nikhil, 26 Nov 2026). Each rollover costs the story's crew half a sprint more (Nikhil, 26 Nov 2026; in v2 it was a full sprint).",
    "decision_why": "A story with an open question is not ready. Before it can be pulled, the product manager and an engineer decide it together in a session of one day (assumption).",
    "rollover_sprint_fraction": 0.5
  },
